function table(headers,rows){return '<div class="dew-scroll" tabindex="0" role="region" aria-label="'+e(L("Scrollable data table","Tableau défilant"))+'"><table><thead><tr>'+headers.map(h=>'<th scope="col">'+e(h)+'</th>').join("")+'</tr></thead><tbody>'+rows.map(r=>"<tr>"+r.map((c,j)=>j===0?'<th scope="row">'+e(c)+'</th>':'<td>'+e(c)+'</td>').join("")+"</tr>").join("")+'</tbody></table></div>'}
const missing=()=>'<p class="notice">'+e(L("No matching published records in this source. Missing or suppressed data are not zero; use the evidence request below.","Aucun dossier publié correspondant dans cette source. Les données manquantes ou supprimées ne valent pas zéro; utiliser la demande de données ci-dessous."))+'</p>';
const sec=(title,body)=>'<section class="dew-box"><h3>'+e(title)+'</h3>'+body+'</section>';
