const guard=async k=>{try{const x=await load(k);sourceStatus[k]="ok";return x}catch{sourceStatus[k]="failed";return null}};
function getProfile(index,o){const r=match(index?.organizations,o);if(!r)return Promise.resolve(null);if(!cache.has(r.path)){const p=fetch(url(r.path)).then(async res=>{if(!res.ok)throw Error("HTTP "+res.status);const b=Uint8Array.from(atob((await res.text()).trim()),c=>c.charCodeAt(0));if(!window.DecompressionStream)throw Error("gzip unsupported");return new Response(new Blob([b]).stream().pipeThrough(new DecompressionStream("gzip"))).json()}).catch(err=>{cache.delete(r.path);throw err});cache.set(r.path,p)}return cache.get(r.path).then(p=>names(o).includes(norm(p.organization))?p:null).catch(()=>null)}
function renderBars(rows,labelIndex,valueIndex,caption){const points=rows.filter(r=>r[valueIndex]!=="—").map(r=>[r[labelIndex],Number(String(r[valueIndex]).replace(/\s/g,"").replace(",",".").replace("%",""))]).filter(r=>Number.isFinite(r[1])&&r[1]>=0&&r[1]<=100);if(!points.length)return "";return "<details><summary>"+e(caption)+"</summary>"+points.map(([k,v])=>"<div><span>"+e(k)+" — "+pct(v)+"</span><span class=\"dew-bar\" aria-hidden=\"true\" style=\"width:"+v+"%\"></span></div>").join("")+"</details>"}
function repr(d,w,o,p){const a=match(d?.orgs,o),b=match(d?.orgs,p),wa=findRow(w||[],o,"Organization"),wb=findRow(w||[],p,"Organization");const rows=[],years=year==="all"?["2017","2018","2019","2020","2021","2022","2023","2024","2025"]:[year];for(const k of Object.keys(groups)){for(const y of years){let x=k==="w"?(y==="2025"&&wa?[wa.Employees,null,wa["Women (%)"],wa["Departmental workforce availability for women (%)"]]:null):a?.[k]?.[y],z=k==="w"?(y==="2025"&&wb?[wb.Employees,null,wb["Women (%)"],wb["Departmental workforce availability for women (%)"]]:null):b?.[k]?.[y];if(!x&&!z)continue;const gap=diff(x?.[2],x?.[3]);const s=k==="w"?url(SRC.women):d?.pages?.[k]?.url||url(SRC.rep);rows.push([t(groups[k]),y,num(x?.[1]),pct(x?.[2]),pct(x?.[3]),pp(gap),...(p?[pct(z?.[2]),pp(diff(z?.[2],z?.[3]))]:[])]);addEvidence("TBS representation",y,t(groups[k]),t(groups[k]),pct(x?.[2]),pct(x?.[3]),pp(gap),num(x?.[1]),s);if(p)addEvidence("TBS representation — "+name(p),y,t(groups[k]),t(groups[k]),pct(z?.[2]),pct(z?.[3]),pp(diff(z?.[2],z?.[3])),num(z?.[1]),s)}}const headers=[L("Group","Groupe"),L("Year","Année"),L("Published group count","Nombre publié du groupe"),L("Representation","Représentation"),L("Availability","Disponibilité"),L("Gap","Écart"),...(p?[name(p)+" "+L("representation","représentation"),name(p)+" "+L("availability gap","écart de disponibilité")]:[])];return rows.length?'<p>'+e(L("March 31 snapshots; core public administration series. Black employee availability is not supplied in this series. Departmental availability is not a hiring target. Changing availability bases limit trend comparisons.","Instantanés au 31 mars; série de l’administration publique centrale. La disponibilité des employés noirs n’est pas fournie. La disponibilité ministérielle n’est pas une cible d’embauche. Les bases de disponibilité changeantes limitent les comparaisons."))+'</p>'+renderBars(rows.map(r=>[r[0]+" · "+r[1],r[3]]),0,1,L("View representation bars by year","Voir les barres de représentation par année"))+table(headers,rows)+sourceNote(SRC.rep,L("Representation source and benchmark metadata","Source et métadonnées de disponibilité"))+sourceNote(SRC.women,L("Women by organization (2025)","Femmes selon l’organisme (2025)")):missing()}
function survey(index,p1,p2,o,p){if(!index)return missing();const qs=lens==="all"?Object.keys(index.definitions):qsets[lens]||[];if(!qs.length)return "";const g=pg==="all"?null:pg,rec=(x)=>g?x?.groups?.[g]?.questions:x?.overall;const a=rec(p1)||{},b=rec(p2)||{};const label=g?(fr()?p1?.groups?.[g]?.fr||p2?.groups?.[g]?.fr||g:g):L("All respondents","Tous les répondants");const rows=qs.filter(q=>index.definitions[q]).map(q=>{const def=index.definitions[q],x=a[q]||[],all=p1?.overall?.[q]||[],z=b[q]||[],kind=def.field==="ANSWER1"?L("Yes","Oui"):def.field==="NEGATIVE"?L("Negative","Négatives"):L("Positive","Positives");const s=g?index.sources.groups:index.sources.overallPublisherUrl;addEvidence("PSES","2024",q+" "+L(def.en,def.fr),label,pct(x[0]),pct(all[0]),pp(diff(x[0],all[0])),num(x[1]),s);if(p)addEvidence("PSES — "+name(p),"2024",q+" "+L(def.en,def.fr),label,pct(z[0]),pct(p2?.overall?.[q]?.[0]),pp(diff(z[0],p2?.overall?.[q]?.[0])),num(z[1]),s);return [q+" · "+L(def.en,def.fr),kind,pct(x[0]),num(x[1]),pct(all[0]),pp(diff(x[0],all[0])),...(p?[pct(z[0]),num(z[1])]:[])]});return (!p1&&!p2?missing():"")+'<p>'+e(L("Published responses, not case counts. Compare like questions and respondent bases; groups overlap. Differences are descriptive, not statistical significance. A higher value may be unfavorable depending on the response type.","Réponses publiées, non nombres de cas. Comparer les mêmes questions et bases; les groupes se chevauchent. Les écarts sont descriptifs, non des tests de signification. Une valeur plus élevée peut être défavorable selon le type de réponse."))+'</p>'+renderBars(rows,0,2,L("View selected survey percentages as bars","Voir les pourcentages du sondage en barres"))+table([L("Question","Question"),L("Response type","Type de réponse"),label,L("Responses (n)","Réponses (n)"),L("All local","Tous locaux"),L("Group minus all","Groupe moins tous"),...(p?[name(p),L("Peer responses (n)","Réponses comparatives (n)")]:[])],rows)+sourceNote(g?index.sources.groups:index.sources.overallPublisherUrl,L("Original 2024 PSES source","Source originale du SAFF 2024"))}
function staffing(d,o,p){if(!d)return missing();const a=match(d.orgs,o),b=match(d.orgs,p);const qs=lens==="all"?Object.keys(d.questions):sqsets[lens]||[];if(!qs.length)return "";const label=t(sg[group]);const rows=qs.map(q=>{const def=d.questions[q],x=a?.[group]?.[q],all=a?.all?.[q],z=b?.[group]?.[q];addEvidence("SNPS","2025",q+" "+L(def.en,def.fr),label,pct(x),pct(all),pp(diff(x,all)),"",d.dataset);if(p)addEvidence("SNPS — "+name(p),"2025",q+" "+L(def.en,def.fr),label,pct(z),pct(b?.all?.[q]),pp(diff(z,b?.all?.[q])),"",d.dataset);return [q+" · "+L(def.en,def.fr),L(def.base,def.base_fr),pct(x),pct(all),pp(diff(x,all)),...(p?[pct(z),pct(b?.all?.[q])]:[])]});return (!a&&!b?missing():"")+'<p>'+e(L("Weighted survey percentages; denominators differ by question. An offer or acting experience share is not an administrative promotion rate. See the source methodology.","Pourcentages pondérés; les dénominateurs varient selon la question. Une proportion d’offres ou d’intérims n’est pas un taux administratif de promotion. Voir la méthode source."))+'</p>'+renderBars(rows,0,2,L("View staffing survey percentages as bars","Voir les pourcentages de dotation en barres"))+table([L("Question","Question"),L("Respondent base","Population de répondants"),label,L("All local","Tous locaux"),L("Group minus all","Groupe moins tous"),...(p?[name(p),name(p)+" "+L("all","tous")]:[])],rows)+sourceNote(L(d.dataset,d.dataset_fr),L("PSC original source and methods","Source originale et méthode de la CFP"))}
function commitments(d,o,p){if(!d)return missing();let out="";for(const x of [o,p].filter(Boolean)){const z=ctaMatch(d.organizations,x);out+='<h4>'+e(name(x))+'</h4>';if(!z){out+=missing();continue}const blocks=[["2021",L("Commitments","Engagements"),z.letter?.commitments,z.letter?.url],["2021",L("Targets stated","Cibles déclarées"),z.letter?.targets,z.letter?.url],["2024",L("Goals","Objectifs"),Object.entries(z.self_assessment?.goals||{}).map(([k,v])=>k.replace(/_/g," ")+" — "+(v.status==="set"?L("reported as set","déclaré fixé"):v.status==="underway"?L("underway","en cours"):L("not stated","non indiqué"))+(v.text?": "+v.text:"")),z.self_assessment?.url],["2024",L("Reported progress","Progrès déclarés"),z.self_assessment?.progress,z.self_assessment?.url],["2024",L("Reported barriers","Obstacles déclarés"),z.self_assessment?.barriers,z.self_assessment?.url]];for(const [yr,title,arr,s] of blocks){if(!arr?.length)continue;out+='<details '+(title===L("Reported barriers","Obstacles déclarés")?'open':'')+'><summary>'+e(yr+" · "+title+" ("+arr.length+")")+'</summary><ol>'+arr.map(v=>'<li>'+e(v)+'</li>').join("")+'</ol>'+sourceNote(s,L("Original report","Rapport original"))+'</details>';for(const v of arr)addEvidence("CTA — "+name(x),yr,title,"",v,"","","",s)}}return '<p>'+e(L("Source summaries may be in English; consult the original bilingual documents. A reported goal or action is not independent evidence of effectiveness.","Les résumés sources peuvent être en anglais; consulter les documents originaux bilingues. Un objectif ou une action déclarés ne prouvent pas indépendamment leur efficacité."))+'</p>'+out}
function hiring(d,o,p){if(!d)return missing();let out="";for(const x of [o,p].filter(Boolean)){const a=match(d.hiring,x);if(!a?.years)continue;const rows=Object.entries(a.years).sort((a,b)=>b[0].localeCompare(a[0])).map(([y,v])=>{addEvidence("PSC appointments — "+name(x),y,L("Appointments by equity self-identification","Nominations selon l’auto-identification"),"",num(v[0]),num(v[1]),"","",url(SRC.hiring));return [y,num(v[0]),num(v[1])]});out+='<h4>'+e(name(x))+'</h4>'+table([L("Fiscal year","Exercice"),L("Self-identified in at least one EE group","Auto-identification à au moins un groupe"),L("Did not self-identify","Sans auto-identification")],rows)}return out?'<p>'+e(L("Appointment counts, not unique employees or group-specific promotion rates. No individual equity-group breakdown in this table.","Nombres de nominations, non personnes uniques ni taux de promotion par groupe. Aucune ventilation par groupe d’équité dans ce tableau."))+'</p>'+out+sourceNote(SRC.hiring,L("PSC staffing data","Données de dotation de la CFP")):missing()}
function executives(raw,o,p){if(!raw)return missing();const list=csv(raw);const rows=list.filter(r=>[o,p].filter(Boolean).some(x=>names(x).includes(norm(r["Department or agency"])))).map(r=>{addEvidence("TBS executive population",r.Year,r.Executives,r["Department or agency"],num(r["Number of employees"]),"","","",url(SRC.ex));return [r["Department or agency"],r.Year,r.Universe,r.Executives,num(r["Number of employees"])]}).sort((a,b)=>String(b[1]).localeCompare(String(a[1])));return rows.length?'<p>'+e(L("Total executive/non-executive headcounts only, not equity group representation. Population may differ from employment-equity coverage.","Effectifs totaux des cadres/non-cadres seulement, non représentation des groupes d’équité. La population peut différer de celle de l’équité en emploi."))+'</p>'+table([L("Organization","Organisme"),L("Year","Année"),L("Universe","Univers"),L("Category","Catégorie"),L("Count","Nombre")],rows)+sourceNote(SRC.ex,L("Original headcount data","Données originales d’effectif")):missing()}
