function inventory(pubs,psc,cat,added,o){const docs=match(pubs?.organizations,o),files=psc?.files||[],catalog=cat?.files||[];let out=docs?.plan?'<p>'+link(docs.plan,L("Official departmental plan","Plan ministériel officiel"))+'</p>':"";out+=(docs?.publications||[]).map(d=>'<p>'+link(d.url,d.title)+'</p>').join("");const list=[];for(const f of files){const hits=Object.entries(f.organizations||{}).filter(([n])=>names(o).includes(norm(n)));if(hits.length!==1)continue;const c=catalog.find(x=>x.file===f.file),label=c?L(c.en,c.fr):f.file;if(lens==="language"&&!/lang|lingu|fol/i.test(label+" "+f.file+" "+f.columns.join(" ")))continue;list.push([label,hits[0][0],hits[0][1],c?.years?.join(" – ")||"",url("data/psc/"+f.file),c?.url||""])}
const ao=match(added?.organizations,o)||Object.values(added?.organizations||{}).find(x=>names(o).includes(norm(x.en)));if(ao){for(const f of added.tables||[]){if(f.scope!=="org"||!ao.t?.[f.id])continue;const label=L(f.titleEn,f.titleFr);if(lens==="language"&&!/lang|lingu|fol/i.test(label+" "+f.id))continue;const path=(fr()?f.fr?.path:f.en?.path)||f.en?.path||f.fr?.path;list.push([label,ao.en,L("Indexed","Indexé"),(f.period||[]).join(" – "),path?url(path):"",f.url||""])}}
if(list.length){out+='<p>'+e(L("Source inventory: row counts are source records, not employee counts. Files can contain multiple organizations; use the linked department profile for filtered tables.","Inventaire : les nombres de lignes sont des enregistrements sources, non des employés. Les fichiers peuvent contenir plusieurs organismes; utiliser le profil ministériel pour les tableaux filtrés."))+'</p><div class="dew-scroll"><table><thead><tr>'+[L("Dataset","Jeu de données"),L("Published label","Libellé publié"),L("Rows / coverage","Lignes / couverture"),L("Period","Période"),L("Files and source","Fichiers et source")].map(h=>'<th>'+e(h)+'</th>').join("")+'</tr></thead><tbody>'+list.map(r=>'<tr>'+r.slice(0,4).map(v=>'<td>'+e(v)+'</td>').join("")+'<td>'+(r[4]?link(r[4],L("File","Fichier")):"")+(r[5]?" · "+link(r[5],L("Publisher","Éditeur")):"")+'</td></tr>').join("")+'</tbody></table></div>';for(const r of list)citations.push(r[4],r[5])}return out||missing()}
function download(name,rows,asCSV=false){const a=document.createElement("a"),s=asCSV?"\ufeff"+rows.map(r=>r.map(v=>{let x=String(v??"");if(/^\s*[=+@]/.test(x)||/^\s*-(?!\d)/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"'}).join(",")).join("\r\n"):rows;a.href=URL.createObjectURL(new Blob([s],{type:asCSV?"text/csv;charset=utf-8":"text/plain;charset=utf-8"}));a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000)}
/* Indicator-to-process crosswalk: a diagnostic prompt, never a causal finding. */
let selectedIndicator=-1;
const indicatorMap={Q12:["cu1","cu2"],Q24:["h1","h2","cu2"],Q25:["mh1","h1"],Q42:["h1"],Q43:["c2","c3"],Q44e:["a3"],Q45:["c1","c3"],Q47:["cu2"],Q49:["ct1","h2"],Q51:["mh1","h2"],Q52:["ct1","ct2"],Q53:["cu2","h2"],Q58:["h1","mh1"],Q63:["h1"],Q65:["h2","h1"],Q70:["h1","h2"],Q72:["h1","h2"],Q73p:["a1","mh1"],Q73q:["mh1","h2"],Q77:["mh2","mh1"],Q78:["mh2"],Q81:["mh1","mh2"],Q84:["a1","a2"],Q85:["a1"],Q86:["a1","a2"],Q87:["a1","a2"],Q88:["a1","h1"],STA_14A:["s1","s2","s4"],STA_13:["s2","s4"],STA_01A:["s1","s3","s4"],STA_01E:["s4","s2"],STA_01F:["s3","s4"],STA_09C:["s1","s2","s4"],STA_04:["c1","c3"]};
function linkedActions(r){if(!r)return [];const code=r[2]?.match(/^(Q\d+[a-z]?|STA_\w+)\b/)?.[1];if(code&&indicatorMap[code])return indicatorMap[code];if(r[0]==="TBS representation")return ["r1","r2"];if(r[0].startsWith("CTA"))return ["ct1","ct2"];if(r[0].startsWith("PSC appointments"))return ["s1","s4"];if(r[0]==="TBS first official language")return ["l1","l2"];if(r[0]==="TBS executive population")return ["c3","r2"];return ["ds1"]}
function indicatorPanel(){const local=name(getOrg(org));const usable=evidence.map((r,j)=>[j,r]).filter(([j,r])=>r[4]!=="—"&&r[4]!==""&&(!r[0].includes(" — ")||r[0].endsWith(" — "+local)));return usable.length?'<section class="dew-box"><h3>'+e(L("Choose an actual data point to investigate","Choisir un point de données réel à examiner"))+'</h3><p>'+e(L("This crosswalk connects an indicator to plausible process-level review steps, not a determination of why that result occurred. Select a metric or commitment below.","Cette correspondance relie un indicateur à des étapes plausibles d’examen des processus, non à une détermination de la cause du résultat. Choisir un indicateur ou engagement ci-dessous."))+'</p><label for="dew-indicator">'+e(L("Published indicator or commitment","Indicateur ou engagement publié"))+'</label><select id="dew-indicator">'+options([["-1",L("Select one evidence item","Sélectionner un élément de preuve")],...usable.map(([j,r])=>[j,r[1]+" · "+r[2]+" · "+r[4]])],selectedIndicator)+'</select><div id="dew-indicator-detail"></div></section>':""}
function showIndicator(){const box=$("indicator-detail");if(!box)return;const r=evidence[selectedIndicator];if(!r){box.innerHTML="";return}const ids=linkedActions(r), aa=actions.filter(a=>ids.includes(a.id));box.innerHTML='<dl><dt>'+e(L("Selected evidence","Preuve sélectionnée"))+'</dt><dd>'+e(r[2])+'</dd><dt>'+e(L("Value and comparison (where published)","Valeur et comparaison (si publiées)"))+'</dt><dd>'+e(r[4]+(r[5]&&r[5]!=="—"?" / "+r[5]:"")+(r[6]&&r[6]!=="—"?" · "+r[6]:""))+'</dd></dl>'+(r[8]?sourceNote(r[8],L("Original source","Source originale")):"")+'<p>'+e(L("Suggested processes to review","Processus proposés à examiner"))+'</p><ul>'+aa.map(a=>'<li><strong>'+e(t(a.title))+'</strong> — '+e(t(a.change))+'</li>').join("")+'</ul><button id="dew-add-linked">'+e(L("Add these review actions to the brief","Ajouter ces actions à la note"))+'</button><p id="dew-add-status" role="status"></p>';$("add-linked").onclick=()=>{ids.forEach(id=>chosen.add(id));notify("actions");host.querySelectorAll("[data-action]").forEach(el=>{el.checked=chosen.has(el.dataset.action)});$("add-status").textContent=L("Added recommended review actions to your brief. You can edit the selection below or in other evidence topics.","Actions d’examen ajoutées à votre note. Vous pouvez modifier la sélection ci-dessous ou dans d’autres thèmes.")}}

function actionPanel(){const subset=actions.filter(a=>lens==="all"||a.lens===lens||a.lens==="sources");const body='<p>'+e(L("Choose concrete process changes to investigate using the selected evidence. These are proposed actions, not findings about the department. Select an action and record the exact data point or reported commitment that supports your review.","Choisir des changements de processus concrets à examiner à partir des données sélectionnées. Ce sont des actions proposées, non des conclusions sur le ministère. Sélectionnez une action et consignez le point de données ou l’engagement précis."))+'</p><div class="dew-actions">'+subset.map(a=>'<details open><summary>'+e(t(a.title))+'</summary><label><input type="checkbox" data-action="'+e(a.id)+'" '+(chosen.has(a.id)?"checked":"")+'>'+e(L("Include in action plan","Inclure dans le plan"))+'</label><dl><dt>'+e(L("Process change","Modification du processus"))+'</dt><dd>'+e(t(a.change))+'</dd><dt>'+e(L("Proposed responsible function","Fonction responsable proposée"))+'</dt><dd>'+e(t(a.owner))+'</dd><dt>'+e(L("Measure","Indicateur"))+'</dt><dd>'+e(t(a.measure))+'</dd><dt>'+e(L("Evidence request","Demande de données"))+'</dt><dd>'+e(t(a.request))+'</dd></dl></details>').join("")+'</div><label for="dew-note">'+e(L("Non-identifying evidence, local barrier, owner, deadline and decision options","Preuves non identificatoires, obstacle local, responsable, échéance et options"))+'</label><textarea id="dew-note" maxlength="2500">'+e(extraNote)+'</textarea><div class="dew-tabs"><button id="dew-build">'+e(L("Generate departmental action brief","Produire une note d’action ministérielle"))+'</button><button id="dew-export">'+e(L("Download brief","Télécharger la note"))+'</button><button id="dew-csv">'+e(L("Download displayed evidence (.csv)","Télécharger les données affichées (.csv)"))+'</button></div><pre id="dew-report" style="white-space:pre-wrap;overflow-wrap:anywhere" aria-live="polite">'+e(report)+'</pre>';return sec(L("From evidence to specific changes","Des données aux changements concrets"),body)}
